function heaviestDistinctWindow(nums: number[]): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    const seen = new Set<number>();
    let sum = 0;
    for (let j = i; j < nums.length && !seen.has(nums[j]); j++) {
      seen.add(nums[j]);
      sum += nums[j];
      best = Math.max(best, sum);
    }
  }
  return best;
}

