function heaviestDistinctWindow(nums: number[]): number {
  const last = new Map<number, number>();
  const prefix = [0];
  for (const v of nums) prefix.push(prefix[prefix.length - 1] + v);
  let left = 0, best = 0;
  nums.forEach((v, right) => {
    const prev = last.get(v);
    if (prev !== undefined && prev >= left) left = prev + 1;
    last.set(v, right);
    best = Math.max(best, prefix[right + 1] - prefix[left]);
  });
  return best;
}

